    "tiebreak": "\u0422\u0410\u0419-\u0411\u0420\u0415\u0419\u041A",
    "tiebreakText": "\u041A\u043E\u043C\u0430\u043D\u0434\u0438 \u043C\u0430\u044E\u0442\u044C \u043E\u0434\u043D\u0430\u043A\u043E\u0432\u0438\u0439 \u043D\u0430\u0439\u043A\u0440\u0430\u0449\u0438\u0439 \u0440\u0430\u0445\u0443\u043D\u043E\u043A. \u041F\u0435\u0440\u0435\u043C\u043E\u0436\u0446\u044F \u0432\u0438\u0437\u043D\u0430\u0447\u0438\u0442\u044C \u0442\u0430\u0439-\u0431\u0440\u0435\u0439\u043A.",
    "tiebreakCycle": "\u0421\u0435\u0440\u0456\u044F",
