    "round3Title": "\u0420\u0430\u0443\u043D\u0434 3 \u2014 \u041F\u0430\u043D\u0442\u043E\u043C\u0456\u043C\u0430",
    "quickRulesTitle": "\u041A\u043E\u0440\u043E\u0442\u043A\u0456 \u043F\u0440\u0430\u0432\u0438\u043B\u0430",
    "quickRulesIntro": "\u0422\u0440\u0438 \u0440\u0430\u0443\u043D\u0434\u0438. \u0422\u0456 \u0441\u0430\u043C\u0456 \u0441\u043B\u043E\u0432\u0430. \u0420\u0456\u0437\u043D\u0456 \u0441\u043F\u043E\u0441\u043E\u0431\u0438 \u043F\u043E\u044F\u0441\u043D\u0435\u043D\u043D\u044F.",
    "quickGoal": "\u0412\u0456\u0434\u0433\u0430\u0434\u0443\u0439\u0442\u0435 \u0441\u043B\u043E\u0432\u0430 \u0440\u0430\u0437\u043E\u043C \u0456\u0437 \u043A\u043E\u043C\u0430\u043D\u0434\u043E\u044E. \u041A\u043E\u0436\u043D\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u0435 \u0441\u043B\u043E\u0432\u043E = 1 \u043E\u0447\u043A\u043E.",
    "quickR1": "\u0420\u0430\u0443\u043D\u0434 1 \u2014 \u041F\u043E\u044F\u0441\u043D\u044E\u0439\u0442\u0435, \u043D\u0435 \u043D\u0430\u0437\u0438\u0432\u0430\u044E\u0447\u0438 \u0441\u0430\u043C\u0435 \u0441\u043B\u043E\u0432\u043E.",
    "quickR2": "\u0420\u0430\u0443\u043D\u0434 2 \u2014 \u041B\u0438\u0448\u0435 \u043E\u0434\u043D\u0435 \u0441\u043B\u043E\u0432\u043E-\u043F\u0456\u0434\u043A\u0430\u0437\u043A\u0430.",
    "quickR3": "\u0420\u0430\u0443\u043D\u0434 3 \u2014 \u041F\u043E\u043A\u0430\u0437\u0443\u0439\u0442\u0435 \u043B\u0438\u0448\u0435 \u0436\u0435\u0441\u0442\u0430\u043C\u0438.",
