    "tiebreak": "\u0422\u0410\u0419-\u0411\u0420\u0415\u0419\u041A",
    "tiebreakText": "\u0423 \u043A\u043E\u043C\u0430\u043D\u0434 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0439 \u043B\u0443\u0447\u0448\u0438\u0439 \u0441\u0447\u0451\u0442. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442 \u0442\u0430\u0439-\u0431\u0440\u0435\u0439\u043A.",
    "tiebreakCycle": "\u0421\u0435\u0440\u0438\u044F",
    "tiebreakRule": "\u041A\u0430\u0436\u0434\u0430\u044F \u043A\u043E\u043C\u0430\u043D\u0434\u0430 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0434\u0438\u043D \u0445\u043E\u0434: 30 \u0441\u0435\u043A\u0443\u043D\u0434, \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u0431\u0435\u0437 \u0441\u043B\u043E\u0432. \u0415\u0441\u043B\u0438 \u0441\u043D\u043E\u0432\u0430 \u043D\u0438\u0447\u044C\u044F \u2014 \u0438\u0433\u0440\u0430\u0435\u043C \u0435\u0449\u0451 \u043E\u0434\u043D\u0443 \u0441\u0435\u0440\u0438\u044E.",
